  `exit_permit` varchar(100) DEFAULT NULL COMMENT '出门单',
  `parking_spot` varchar(100) DEFAULT NULL COMMENT '停车位',
  `location_info` varchar(255) DEFAULT NULL COMMENT '位置信息',
  `latitude` double DEFAULT NULL COMMENT '纬度',
  `longitude` double DEFAULT NULL COMMENT '经度',
  `data_source` varchar(50) NOT NULL DEFAULT 'manual' COMMENT '数据来源',
  `vehicle_status` varchar(50) DEFAULT NULL COMMENT '车辆状态',
  `rear_motor_no` varchar(100) DEFAULT NULL COMMENT '后电机号',
  `monitor_method` varchar(100) DEFAULT NULL COMMENT '监控方式',
  `battery_pack_part_no` varchar(100) DEFAULT NULL COMMENT '电池包零件号',
  `battery_pack_rated` varchar(100) DEFAULT NULL COMMENT '电池包额定电量',
  `borrower_id` varchar(50) DEFAULT NULL COMMENT '借车人ID',
  `temp_plate_insurance_count` int DEFAULT NULL COMMENT '临牌&保险办理次数',
  `front_motor_no` varchar(100) DEFAULT NULL COMMENT '前电机号',
  `vehicle_manager_id` varchar(50) DEFAULT NULL COMMENT '车管ID',
  `trial_plan` varchar(255) DEFAULT NULL COMMENT '试验策划',
  `dept_l2` varchar(100) DEFAULT NULL COMMENT '二级部门',
  `address_detail` varchar(255) DEFAULT NULL COMMENT '详细地址',
  `temp_plate_info` varchar(255) DEFAULT NULL COMMENT '临牌信息',
  `battery_pack_trace` varchar(255) DEFAULT NULL COMMENT '电池包溯源码',
  `borrow_days` int DEFAULT NULL COMMENT '借用天数',
  `temp_plate_valid_area` varchar(255) DEFAULT NULL COMMENT '临牌有效区域',
  `province` varchar(50) DEFAULT NULL COMMENT '车辆所在省',
  `borrower_account` varchar(50) DEFAULT NULL COMMENT '借车人账号',
  `battery_pack_status` varchar(100) DEFAULT NULL COMMENT '电池包状态',
  `trial_plan_id` varchar(100) DEFAULT NULL COMMENT '试验策划ID',
  `vehicle_model_config` varchar(100) DEFAULT NULL COMMENT '车型配置',
  `vehicle_phase` varchar(50) DEFAULT NULL COMMENT '车辆阶段',
  `feishu_record_id` varchar(100) DEFAULT NULL COMMENT '飞书记录ID',
  `storage_days` int DEFAULT NULL COMMENT '在库时长',
  `key_location` varchar(100) DEFAULT NULL COMMENT '钥匙位置',
  `is_monitored` varchar(50) DEFAULT NULL COMMENT '是否监控',
  `engine_no` varchar(100) DEFAULT NULL COMMENT '发动机号',
  `qr_code` varchar(255) DEFAULT NULL COMMENT '二维码',
