  `borrower_phone` varchar(30) DEFAULT NULL COMMENT '电话',
  `vehicle_status_note` varchar(255) DEFAULT NULL COMMENT '车辆状态备注',
  `is_under_modification` varchar(50) DEFAULT NULL COMMENT '改制中',
  `dept_l1` varchar(100) DEFAULT NULL COMMENT '一级部门',
  `is_first_vin_record` varchar(50) DEFAULT NULL COMMENT '是否VIN最早记录',
  `borrower_7day_rate` double DEFAULT NULL COMMENT '当前借用人7日利用率(%)',
  `borrow_time` varchar(50) DEFAULT NULL COMMENT '借车时间',
  `vehicle_manager` varchar(50) DEFAULT NULL COMMENT '车管',
  `temp_plate_area` varchar(255) DEFAULT NULL COMMENT '临牌区域',
